#!/usr/bin/env python3
"""Build a maximum-scale request and time the submission against it."""
import json
import os
import random
import subprocess
import sys
import time

MAIN = '/workspace/submission/main.py'


def connected_graph(rng, nodes, links):
    edges = set()
    for i in range(1, nodes):
        j = rng.randrange(i)
        edges.add((min(i, j), max(i, j)))
    degree = {i: 0 for i in range(nodes)}
    for a, b in edges:
        degree[a] += 1
        degree[b] += 1
    tries = 0
    while len(edges) < links and tries < links * 200:
        tries += 1
        a, b = rng.randrange(nodes), rng.randrange(nodes)
        if a == b or (min(a, b), max(a, b)) in edges:
            continue
        if degree[a] >= 8 or degree[b] >= 8:
            continue
        edges.add((a, b))
        degree[a] += 1
        degree[b] += 1
    return sorted(edges)


def paths_between(adj, src, dst, limit, maxlen):
    out = []
    stack = [[src]]
    while stack and len(out) < limit:
        p = stack.pop()
        last = p[-1]
        if last == dst:
            out.append(p)
            continue
        if len(p) >= maxlen:
            continue
        for nxt in sorted(adj.get(last, ()), key=lambda n: rng.random()):
            if nxt not in p:
                stack.append(p + [nxt])
    return out


rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 4)
streams = []
budget = 8192
for s in range(8):
    nodes = 256
    links_n = min(512, budget // 2 if s == 7 else 512)
    edges = connected_graph(rng, nodes, links_n)
    names = ["N%04d" % i for i in range(nodes)]
    externals = rng.sample(range(nodes), 16)
    topo = {"nodes": [{"id": i, "name": names[i],
                       "external_capacity": rng.choice([10 ** 9, 5000, 250])}
                      for i in range(nodes)],
            "links": [{"source": a, "target": b,
                       "capacity": rng.choice([10 ** 9, 400, 7])} for a, b in edges],
            "external_nodes": [names[i] for i in externals]}
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    plan = {}
    hops = 0
    for snode in externals:
        row = {}
        for dnode in externals:
            if snode == dnode:
                continue
            cand = paths_between(adj, snode, dnode, 2, 12)
            if not cand:
                cand = [[snode, dnode]] if dnode in adj.get(snode, ()) else None
            if cand is None:
                continue
            chosen = cand[:1]
            hops += sum(len(p) - 1 for p in chosen)
            weights = [1000 // len(chosen)] * len(chosen)
            weights[-1] += 1000 - sum(weights)
            row[names[dnode]] = [{"path": [names[v] for v in p], "weight": w}
                                 for p, w in zip(chosen, weights)]
        if row:
            plan[names[snode]] = row
    counters = {}
    for a, b in edges:
        cap = 60
        counters["low_%s_egress_to_%s" % (names[a], names[b])] = {
            "perturbed": rng.randint(0, 40)}
        counters["low_%s_ingress_from_%s" % (names[b], names[a])] = {
            "perturbed": rng.randint(0, 40) if rng.random() < .9 else None}
    for i in externals:
        counters["low_%s_origination" % names[i]] = {"perturbed": rng.randint(0, 40)}
        counters["low_%s_termination" % names[i]] = {"perturbed": rng.randint(0, 40)}
    demands = [[a, b, rng.randint(0, 30)] for a in externals for b in externals
               if a != b]
    events = [{"op": "patch", "demands": demands, "counters": counters},
              {"op": "routes", "label": "p0", "paths": plan}]
    flows = 2 * len(edges) + 2 * len(externals)
    repairs = 1
    budget -= flows
    for r in range(repairs):
        events.append({"op": "repair", "id": "snap%d_%d" % (s, r)})
    for v in range(6):
        events.append({"op": "validate", "id": "snap%d_0" % s})
        events.append({"op": "patch",
                       "demands": [[externals[0], externals[1], rng.randint(0, 30)]],
                       "counters": {}})
    streams.append({"topology": topo,
                    "settings": {"trials": 32, "epsilon": 100000, "seed": 991,
                                 "cutoff": [1, 2], "bias": 24000, "tau": 50000,
                                 "gamma": [4, 5], "cache_slots": 8},
                    "events": events})
    print("stream", s, "flows", flows, "plan hops", hops, "budget left", budget)

request = {"streams": streams}
blob = json.dumps(request, separators=(",", ":"))
print("request bytes", len(blob))
path = '/workspace/tmp/scratch/perf.json'
with open(path, 'w') as handle:
    handle.write(blob)
start = time.time()
proc = subprocess.run([sys.executable, '-B', '-u', MAIN], stdin=open(path, 'rb'),
                      capture_output=True, cwd='/workspace/tmp/scratch',
                      env={'PATH': '/usr/local/bin:/usr/bin:/bin',
                           'PYTHONPATH': '/workspace/submission',
                           'CROSSCHECK_DEBUG': '1'})
print("elapsed %.2fs rc=%s out=%d bytes" % (time.time() - start, proc.returncode,
                                            len(proc.stdout)))
if proc.stderr:
    print(proc.stderr.decode()[:2000])
PYEOF
